/** WKS-I00-R01-DEVOL: un renglón del archivo I01-DEVOLUCION (COMP = decimal empacado en MCP). */
public record Devolucion(
        String contrato,                 // 9(12)
        String medioAcceso,              // 9(12) REDEFINES sucursal 9(04) + cuenta 9(08)
        int claveMovimiento,             // 9(04): 2001, 2002, 2113...
        long numCheque,                  // 9(10)
        BigDecimal importe,              // 9(12)V99 -> escala 2
        int sucursalPromotora, int bancoEnvio, int contador,
        AutorizacionTransaccion autoriza, // 9(14) REDEFINES suc 9(04) + caja 9(02) + secuencia 9(08)
        int causaDevolucion,             // 9(02): 1 = fondos insuficientes
        char subcausa, int horaDevolucion,
        EstatusDevolucion estatus,       // 99 COMP
        String nombreCliente, int moneda, LocalDate fechaDevolucion,
        BigDecimal diferenciaSaldo,      // WKS-I00-R01-DIFSDOB08 9(12)V99
        BigDecimal comisionCobrada,      // 9(04)V99
        int tipoCobro) {}

/** Catálogo WKS-I00-R01-STATUS-DEV (fuente de verdad del ciclo de devolución). */
public enum EstatusDevolucion {
    DEVOLUCION(0), COBRADO_POSTERIOR(1), SALDO_SUFICIENTE(2), DUPLICADO(3),
    SIN_COBRO_POR_BLOQUEO(4),      // bloqueo 66 con restricciones 17
    NO_EXISTE_CONTRATO(5),
    NO_COBRA_PRODUCTO(6),          // faltan claves en B05 o B17
    RECUPERADO_TOTAL_S408(7),
    ERROR_CLAVE(8),                // no es 2001, 2002 ni 2113
    ELIMINADO(9),
    CAUSA_NO_FONDOS(10);           // causa distinta a fondos insuficientes

    private final int codigo;
    EstatusDevolucion(int codigo) { this.codigo = codigo; }
    public int codigo() { return codigo; }
    public static EstatusDevolucion of(int c) {
        return Arrays.stream(values()).filter(e -> e.codigo == c).findFirst()
                .orElseThrow(() -> new IllegalArgumentException("STATUS-DEV desconocido: " + c));
    }
}

