p120:
  punteo:
    entrada: "S500/FILE/P102/PUNTEO/{csi}/{fecha}"     # WKS-TIT-PUNTEOIN
    salida:  "S500/FILE/P120/PUNTEO/{csi}/{fecha}"     # WKS-TIT-PUNTEO
    paso-origen: P102
    copia-origen: 1

@Component
@RequiredArgsConstructor
class PunteoPassThroughTasklet implements Tasklet {
    private final P120Properties props;
    private final ProcesoContext ctx;                   // fecha base y CSI del nodo

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext cc) throws Exception {
        try (var in = punteoReader(props.punteo().entrada()); var out = punteoWriter(props.punteo().salida())) {
            PunteoHeader h = in.readHeader()
                    .orElseThrow(() -> new ProcesoAbortadoException("ARCH PUNTEO VACIO"));
            boolean valido = h.tipoRegistro() == 0
                    && h.sistemaOrigen() == 500 && h.sistemaDestino() == 500
                    && h.fechaMovimiento().equals(ctx.fechaBase())
                    && h.csiOrigen() == ctx.csi()
                    && props.punteo().pasoOrigen().equals(h.paso())
                    && h.copia() == props.punteo().copiaOrigen();
            if (!valido) throw new ProcesoAbortadoException("ERR HEADER PUNTEO " + h.raw());   // DMTERMINATE

            out.write(PunteoHeader.deP120(ctx));                         // 50002100-ARMA-HEADER
            for (PunteoDetalle d; (d = in.readDetalle()) != null && d.tipoRegistro() != 99; ) {
                out.write(d);                                            // se re-emite el punteo de P102 tal cual
            }
        }
        return RepeatStatus.FINISHED;
    }
}

@Component
@StepScope
@RequiredArgsConstructor
public class DevolucionProcessor implements ItemProcessor<Devolucion, Devolucion> {

    private final ContratoService contratos;          // 50003100-VERIFICA-CTO (LOCK B03SXCTO)
    private final TarifaDevolucion tarifas;           // 50003600-DAME-TARIFA
    private final CobroComision cobro;                // 50004000-COBRA-COMISION

    @Override
    public Devolucion process(Devolucion d) {
        Optional<ContratoVista> cto = contratos.verifica(d.contrato());
        if (cto.isEmpty()) return d.conEstatus(EstatusDevolucion.NO_EXISTE_CONTRATO);   // vía MODIF-ARCHIVO

        ContratoVista c = cto.get();
        if (d.estatus() == EstatusDevolucion.ELIMINADO) return d;
        if (c.tipoBloqueo() == 66 && c.restricciones() == 17) {
            return d.conEstatus(EstatusDevolucion.SIN_COBRO_POR_BLOQUEO);
        }
        if (c.esTesofe()) return d.conEstatus(EstatusDevolucion.DEVOLUCION);  // no se cobra; ver riesgo
        if (d.causaDevolucion() != 1) return d.conEstatus(EstatusDevolucion.CAUSA_NO_FONDOS);

        ResultadoTarifa t = tarifas.resuelve(d, c);
        return t.cobrable() ? cobro.cobra(d, c, t) : d.conEstatus(t.estatusNoCobro());
    }
}
// La ruptura por contrato y medio de acceso (W77-FIN-CTO, WKS-IGUAL-MDA) pasa a un
// ItemWriter que agrupa por contrato: el archivo ya viene ordenado por SORT S01-SORTDEVOL.

@Component
class TarifaDevolucion {

    /** 50003610-TARIFA-DEVOL. Índice de clave B05: 17 para la 2001, 18 para la 2002. */
    ResultadoTarifa resuelve(Devolucion d, ContratoVista c) {
        Integer indiceClave = switch (d.claveMovimiento()) {
            case 2001 -> 17;
            case 2002 -> 18;
            default -> null;              // 2113 incluida: el fuente la manda a COBRA-INSTR = 8
        };
        if (indiceClave == null) return ResultadoTarifa.noCobra(EstatusDevolucion.ERROR_CLAVE);

        Instrumento inst = c.instrumento();
        if (inst.claveComision(indiceClave) <= 0) {
            return ResultadoTarifa.noCobra(EstatusDevolucion.NO_COBRA_PRODUCTO);
        }
        BigDecimal tope = inst.comisionDevolucionMayor(c.tipoPersona(), c.indiceEsquema());  // 9(8)V99
        // Se cobra el menor entre el tope del tarifario y la diferencia de saldo de B08.
        BigDecimal tarifa = d.diferenciaSaldo().compareTo(tope) > 0 ? tope : d.diferenciaSaldo();
        return ResultadoTarifa.cobra(tarifa.setScale(2, RoundingMode.DOWN));  // MOVE a 9(8)V99 trunca
    }
}

@Component
@RequiredArgsConstructor
class CobroComision {

    /** WKS-TASA-IVA es 9(4)V9(4): factor 1 + tasa (p. ej. 1.1600). */
    CargoComision calcula(BigDecimal tarifa, BigDecimal factorIva, boolean llevaIva, BigDecimal disponible) {
        BigDecimal conIva, sinIva, iva;
        if (llevaIva) {
            conIva = tarifa.multiply(factorIva).setScale(2, RoundingMode.DOWN);   // COMPUTE sin ROUNDED
            sinIva = tarifa;
            iva    = conIva.subtract(sinIva);
        } else {
            conIva = sinIva = tarifa;
            iva    = BigDecimal.ZERO.setScale(2);
        }
        BigDecimal ivaTotal = iva, difCom = BigDecimal.ZERO.setScale(2), difIva = difCom;

        if (disponible.compareTo(conIva) < 0) {                // cobro parcial hasta el disponible
            conIva = disponible;
            if (llevaIva) {
                sinIva = conIva.divide(factorIva, 2, RoundingMode.HALF_UP);   // COMPUTE ... ROUNDED
                iva    = conIva.subtract(sinIva);
                difCom = tarifa.subtract(sinIva);
                difIva = ivaTotal.subtract(iva);
            } else {
                sinIva = disponible;
                iva    = BigDecimal.ZERO.setScale(2);
                difCom = tarifa.subtract(sinIva);
            }
        }
        return new CargoComision(conIva, sinIva, iva, difCom, difIva);
    }

    /** 50004200-CALCULA-DISPONIBLE: el saldo pendiente se integra al actual antes de calcular. */
    static BigDecimal disponible(Contrato c) {
        if (c.getSaldoPendiente().signum() > 0) {
            c.setSaldoActual(c.getSaldoActual().add(c.getSaldoPendiente()));
            c.setSaldoPendiente(BigDecimal.ZERO);
            if (c.getIndLineaCredito() > 0) c.setIndPendienteLc(1);
        }
        return c.getSaldoActual().compareTo(c.getAutPendiente()) > 0
                ? c.getSaldoActual().subtract(c.getAutPendiente()) : BigDecimal.ZERO;
    }
}
// Si queda diferencia y B17-IND-COMIPEND está entre 1 y 99, se suma a B12-IMP-ACUMULADO
// (comisión pendiente); si no, la diferencia se descarta (difCom = difIva = 0).

@Component
@StepScope
class DevolucionArchivoWriter implements ItemWriter<Devolucion> {
    private final TrailerDevolucion trailer = new TrailerDevolucion();   // WKS-I00-R02-*

    /** 50006000-MODIF-ARCHIVO: el estatus ya asignado se respeta; si es 00 se deriva del cobro. */
    static EstatusDevolucion estatusFinal(Devolucion d, boolean contratoExiste, int cobraInstr) {
        if (d.estatus() != EstatusDevolucion.DEVOLUCION) return d.estatus();
        if (!contratoExiste) return EstatusDevolucion.NO_EXISTE_CONTRATO;
        if (cobraInstr == 0)  return EstatusDevolucion.NO_COBRA_PRODUCTO;
        if (cobraInstr == 8)  return EstatusDevolucion.ERROR_CLAVE;
        return EstatusDevolucion.DEVOLUCION;
    }

    @Override
    public void write(Chunk<? extends Devolucion> chunk) {
        for (Devolucion d : chunk) {
            if (d.estatus() == EstatusDevolucion.DEVOLUCION) trailer.sumaDevuelto(d.importe());
            else                                              trailer.sumaSinCobro(d.importe());
            archivo.reescribe(d.conNombre(d.nombreCliente() == null ? "NO EXISTE EN BASE" : d.nombreCliente()));
            trailer.sumaRegistro();
        }
    }
}

@Component
@RequiredArgsConstructor
class ContratoPersistencia {
    private final ContratoRepository b03;
    private final HistoricoRepository b06;
    private final ComisionPendienteRepository b12;
    private final DevolucionMensualRepository b20;

    /**
     * 50007000-ACTUALIZA-BASE. Al cambiar de contrato guarda B03, B06 y B12 si se tocaron;
     * B20 se guarda también al cambiar solo de medio de acceso. Cualquier error aborta el job.
     */
    @Transactional
    public void guarda(EstadoContrato e, boolean finContrato, LocalDate fechaBase) {
        if (finContrato && e.huboMovimientoBatch()) {
            e.contrato().setFechaUltimaActualizacion(fechaBase);     // B03-FEC-ULTACT
            e.marcaB03();
        }
        if (finContrato) {
            if (e.tocoB03()) b03.save(e.contrato());
            if (e.tocoB06()) b06.save(e.historico());
            if (e.tocoB12()) b12.save(e.comisionPendiente());
        }
        if (e.tocoB20()) b20.save(e.devolucionMensual());
        e.limpiaMarcas(finContrato);                                 // todas, o solo B20
    }
}

