p120:
  comiprev:
    ruta: "(S127)S127/FILE/S500/COMIPREV/{csi}/{fecha}"
    sistema-origen: 127
    sistema-destino: 500
    formato: 2

@Component
@RequiredArgsConstructor
class PrevencionesStepLoop implements JobExecutionDecider {
    private final P120Properties props;
    private final CalendarioBancario calendario;      // LOCSUP función 13, formato 12

    /** 50200000-PREVENCIONES se repite por día hasta alcanzar la fecha próxima de proceso. */
    @Override
    public FlowExecutionStatus decide(JobExecution job, StepExecution ultimo) {
        LocalDate fecha = job.getExecutionContext().get("fechaPrevencion", LocalDate.class);
        LocalDate proxima = job.getExecutionContext().get("fechaProxima", LocalDate.class);
        Resource archivo = recurso(props.comiprev().ruta(), fecha);
        if (!archivo.exists()) {
            if (fecha.isBefore(proxima)) log.warn("ARCHIVO {} NO ESTA RESIDENTE", archivo);
            return new FlowExecutionStatus("FIN");
        }
        if (!ComiPrevValidator.valido(archivo, fecha, props.comiprev())) {
            return new FlowExecutionStatus("ARCHIVO_ERRONEO");     // 60610200-STOP-PROGRAM: alerta al operador
        }
        LocalDate siguiente = calendario.sumaDias(fecha, 1);
        job.getExecutionContext().put("fechaPrevencion", siguiente);
        return new FlowExecutionStatus(siguiente.equals(proxima) ? "ULTIMO_DIA" : "OTRO_DIA");
    }
}

