# application.yml
p120:
  prevenciones:
    contratos-exentos:          # antes: nueve números de contrato compilados en 50200500
      - "****"                  # se cargan desde un catálogo administrado, no desde el código

@Component
@StepScope
@RequiredArgsConstructor
class PrevencionProcessor implements ItemProcessor<ComiPrevRegistro, CargoPrevencion> {
    private final ContratoService contratos;
    private final P120Properties props;
    private final ContadoresPrevencion cont;          // leídos, aceptados, rechazados, extended

    @Override
    public CargoPrevencion process(ComiPrevRegistro r) {
        cont.leido();
        if (r.tipoRegistro() != 2) { cont.rechazado("TIPO DE REG ERRONEO"); return null; }

        var v = contratos.verifica(r.contrato());
        if (v.clonado()) { cont.rechazadoExtended(); return null; }
        if (v.contrato().isEmpty()) { cont.rechazado("NO EXISTE CONTRATO"); return null; }

        ContratoVista c = v.contrato().get();
        boolean excluido = (c.tipoBloqueo() == 66 && c.restricciones() == 17)
                || c.fondoSocialSinComision()                      // W77-SOCFUND-SINCOM
                || c.esTesofe()
                || props.prevenciones().contratosExentos().contains(c.numContrato());
        if (excluido) { cont.rechazado(); return null; }
        return cobroPrevencion.cobra(r, c);                        // 50201000-COBRA-COMPREV
    }
}
